@extends('layouts.app') @section('title','Add Sale') @section('content')<div class="pagehead"><div><h1>Record Daily Sale</h1><div class="muted">Simple sale entry; stock automatically reduce hoga.</div></div><a class="btn secondary" href="/sales">Back</a></div><div class="card"><form method="post" action="/sales">@csrf<div class="row"><div class="field"><label>Date *</label><input type="date" name="sale_date" value="{{ old('sale_date',today()->toDateString()) }}" required></div><div class="field"><label>Customer name</label><input name="customer_name" value="{{ old('customer_name') }}" placeholder="Walk-in customer"></div><div class="field"><label>Sale type *</label><select name="sale_type"><option>Item</option><option>Software</option></select></div></div><div class="row"><div class="field"><label>Item *</label><select name="item_id" id="item" required><option value="">Choose item</option>@foreach($items as $i)<option value="{{ $i->id }}" data-price="{{ $i->selling_price }}" data-qty="{{ $i->quantity }}">{{ $i->name }} — Stock {{ $i->quantity }}</option>@endforeach</select></div><div class="field"><label>Quantity *</label><input type="number" min="1" name="quantity" value="1" required></div><div class="field"><label>Unit sale price (Rs) *</label><input type="number" min="0" step="0.01" id="price" name="unit_price" value="0" required></div></div><div class="row"><div class="field"><label>Discount (Rs)</label><input type="number" min="0" step="0.01" name="discount" value="0"></div><div class="field"><label>Received now (Rs) *</label><input type="number" min="0" step="0.01" name="paid_amount" value="0" required></div></div><div class="field"><label>Remarks</label><textarea name="notes"></textarea></div><button class="btn">Save Sale</button></form></div><script>document.getElementById('item').addEventListener('change',e=>{document.getElementById('price').value=e.target.selectedOptions[0].dataset.price||0})</script>@endsection